const out = [];
const body = $input.first().json.body ?? $input.first().json;
const rows = Array.isArray(body) ? body : (Array.isArray(body.rows) ? body.rows : []);
const batchId = 'BATCH_N8N_' + new Date().toISOString().replace(/[-:T.Z]/g,'').slice(0,14);
rows.forEach((r, i) => {
  const errs = [];
  const amt = Number(r.tx_amount);
  if (!r.tx_id) errs.push('tx_id 누락');
  if (r.tx_amount === undefined || r.tx_amount === null || r.tx_amount === '' || Number.isNaN(amt)) errs.push('tx_amount 파싱 불가');
  const ts = new Date(r.tx_timestamp);
  if (!r.tx_timestamp || isNaN(ts.getTime())) errs.push('tx_timestamp 파싱 불가');
  out.push({ json: {
    batch_id: batchId, row_no: i + 1, schema_error: errs.length > 0, error_detail: errs.join('; '),
    tx_id: r.tx_id ?? null, tx_timestamp: isNaN(ts.getTime()) ? null : ts.toISOString(),
    posting_date: isNaN(ts.getTime()) ? null : ts.toISOString().slice(0,10),
    account_id: r.account_id ?? null, merchant_id: r.merchant_id ?? null,
    merchant_category: r.merchant_category ?? null, tx_type: r.tx_type ?? 'EXPENSE',
    tx_amount: Number.isNaN(amt) ? null : amt, department_code: r.department_code ?? null,
    evidence_doc_no: r.evidence_doc_no ?? null, raw_payload: JSON.stringify(r)
  }});
});
if (out.length === 0) out.push({ json: { batch_id: batchId, row_no: 0, schema_error: false, empty_batch: true } });
return out;
